    'https://images.pexels.com/photos/25489943/pexels-photo-25489943.jpeg?auto=compress&cs=tinysrgb&h=650&w=940',
    'https://images.pexels.com/photos/31273768/pexels-photo-31273768.jpeg?auto=compress&cs=tinysrgb&h=650&w=940',
    'https://images.pexels.com/photos/37644991/pexels-photo-37644991.jpeg?auto=compress&cs=tinysrgb&h=650&w=940',
    'https://images.pexels.com/photos/943528/pexels-photo-943528.jpeg?auto=compress&cs=tinysrgb&h=650&w=940',
    'https://images.pexels.com/photos/6313514/pexels-photo-6313514.jpeg?auto=compress&cs=tinysrgb&h=650&w=940',
    'https://images.pexels.com/photos/6441179/pexels-photo-6441179.jpeg?auto=compress&cs=tinysrgb&h=650&w=940',
    'https://images.pexels.com/photos/35891424/pexels-photo-35891424.jpeg?auto=compress&cs=tinysrgb&h=650&w=940',
    'https://images.pexels.com/photos/6068394/pexels-photo-6068394.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'
  ];
  available_idx INT := 1;
  used_urls TEXT[];
BEGIN
  SELECT array_agg(DISTINCT image_url) INTO used_urls FROM catalogue_listing WHERE status = 'active';
  
  FOR dup_record IN
    SELECT id FROM (
      SELECT id, image_url, title,
        ROW_NUMBER() OVER (PARTITION BY image_url ORDER BY title) as rn
      FROM catalogue_listing WHERE status = 'active'
    ) t WHERE rn > 1 ORDER BY title
  LOOP
    WHILE available_idx <= array_length(img_pool, 1) AND img_pool[available_idx] = ANY(used_urls) LOOP
      available_idx := available_idx + 1;
    END LOOP;
    
    IF available_idx <= array_length(img_pool, 1) THEN
      UPDATE catalogue_listing SET image_url = img_pool[available_idx] WHERE id = dup_record.id;
      used_urls := array_append(used_urls, img_pool[available_idx]);
      available_idx := available_idx + 1;
    END IF;
  END LOOP;
END $$;

-- Fix the one gem duplicate (Café Clock Rooftop shares image with Le Jardin Secret)
UPDATE hidden_gem SET image_url = 'https://images.pexels.com/photos/4502971/pexels-photo-4502971.jpeg?auto=compress&cs=tinysrgb&h=650&w=940' 
WHERE id = 'e2222222-0000-0000-0000-000000000002' 
AND image_url = 'https://images.pexels.com/photos/15531325/pexels-photo-15531325.jpeg?auto=compress&cs=tinysrgb&h=650&w=940';